package com.papaya.claims.claim.api.dto;

import com.papaya.claims.claim.domain.AuditRecord;
import java.time.Instant;
import java.util.UUID;

public record AuditEntryView(UUID id, long sequence, Instant timestamp, String fromState, String toState,
                             String actorId, String role, String reason, String correlationId) {
    public static AuditEntryView from(AuditRecord record) {
        return new AuditEntryView(record.id(), record.sequence(), record.occurredAt(), record.fromState(),
                record.toState(), record.actorId(), record.role(), record.reason(), record.correlationId());
    }
}
package com.papaya.claims.claim.api.dto;

import java.util.List;
import java.util.Objects;

public record ApiError(String code, String message, List<String> details, String correlationId) {
    public ApiError {
        if (code == null || code.isBlank()) throw new IllegalArgumentException("Error code is required");
        if (message == null || message.isBlank()) throw new IllegalArgumentException("Error message is required");
        details = List.copyOf(Objects.requireNonNullElse(details, List.of()));
        correlationId = Objects.requireNonNullElse(correlationId, "");
    }
}
package com.papaya.claims.claim.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

public record Claim(UUID id, String memberId, String state, long version, ClaimFacts facts,
                    Instant createdAt, Instant updatedAt) {
    public Claim {
        Objects.requireNonNull(id, "id");
        if (memberId == null || memberId.isBlank()) throw new IllegalArgumentException("Member id is required");
        if (state == null || state.isBlank()) throw new IllegalArgumentException("Claim state is required");
        if (version < 0) throw new IllegalArgumentException("Claim version cannot be negative");
        Objects.requireNonNull(facts, "facts");
        Objects.requireNonNull(createdAt, "createdAt");
        Objects.requireNonNull(updatedAt, "updatedAt");
    }
}
package com.papaya.claims.claim.domain;

import java.util.Objects;

public record TransitionCommand(String targetState, long expectedVersion, String reason, ClaimFacts suppliedFacts) {
    public TransitionCommand {
        if (targetState == null || targetState.isBlank()) throw new IllegalArgumentException("Target state is required");
        if (expectedVersion < 0) throw new IllegalArgumentException("Expected version cannot be negative");
        reason = Objects.requireNonNullElse(reason, "");
        suppliedFacts = Objects.requireNonNullElseGet(suppliedFacts, () -> new ClaimFacts(java.util.Map.of()));
    }
}
package com.papaya.claims.claim.domain;

import java.util.Objects;

public record TransitionResult(Claim claim, AuditRecord audit, boolean replayed) {
    public TransitionResult {
        Objects.requireNonNull(claim, "claim");
        Objects.requireNonNull(audit, "audit");
    }
}
package com.papaya.claims.claim.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

public record AuditRecord(UUID id, UUID claimId, long sequence, Instant occurredAt, String fromState,
                          String toState, String actorId, String role, String reason,
                          String correlationId, String workflowVersion) {
    public AuditRecord {
        Objects.requireNonNull(id, "id");
        Objects.requireNonNull(claimId, "claimId");
        if (sequence < 0) throw new IllegalArgumentException("Audit sequence cannot be negative");
        Objects.requireNonNull(occurredAt, "occurredAt");
        if (toState == null || toState.isBlank()) throw new IllegalArgumentException("Audit target state is required");
        if (actorId == null || actorId.isBlank()) throw new IllegalArgumentException("Audit actor is required");
        Objects.requireNonNull(role, "role");
        Objects.requireNonNull(reason, "reason");
        Objects.requireNonNull(correlationId, "correlationId");
        Objects.requireNonNull(workflowVersion, "workflowVersion");
    }
}
package com.papaya.claims.claim.domain;

public record PageRequest(int page, int size) {
    public static final int DEFAULT_PAGE = 0;
    public static final int DEFAULT_SIZE = 20;
    public static final int MAX_SIZE = 100;

    public PageRequest {
        if (page < 0) throw new IllegalArgumentException("page must be zero or greater");
        if (size < 1 || size > MAX_SIZE) throw new IllegalArgumentException("size must be between 1 and " + MAX_SIZE);
    }

    public long offset() {
        return Math.multiplyExact((long) page, size);
    }
}
